/-- Coefficients of `S₂ = S_{η₊} - S₁`. -/
noncomputable def a₂ (x : ℝ) (n : ℕ) : ℂ :=
  if n.Prime ∧ √x < n then 0 else ((Λ n * etaPlus (n / x) : ℝ) : ℂ)

